step1-enable-derive.commands:
# Add derive to Cargo.toml dependencies
[dependencies]
atomic_capsule_derive = { version = "0.4.0", path = "../atomic_capsule_derive" }

# Add to lib.rs (ensure derive macros available)
pub use atomic_capsule_derive::ComputationalCapsule;

# Add derive to all capsule structs
find src -name "*.rs" -exec sed -i '/^pub struct.*Capsule/i #[derive(ComputationalCapsule)]' {} \;

step2-remove-manual-macros.automated-removal:
# Remove all manual verification macros (safe to run, backup first)
cd /home/samuel/Primitives/atomic_capsule

# Option 1: Remove all verify_capsule_properties! calls
find src -name "*.rs" -exec sed -i '/verify_capsule_properties!/d' {} \;

# Option 2: Remove all verification module imports
find src -name "*.rs" -exec sed -i '/use.*verification::/d' {} \;

# Option 3: Remove verify_alignment_only! calls
find src -name "*.rs" -exec sed -i '/verify_alignment_only!/d' {} \;

# Validate compilation (should still pass with derive)
cargo build --lib --release

