pattern.code-pattern:
// Typical usage pattern
impl NoGenerationCapsule {
    pub fn update_with_generation(&self, new_state: u64) -> Result<(), ()> {
        loop {
            let old_gen = self.generation.load(Ordering::Acquire);
            let old_state = self.state.load(Ordering::Acquire);

            // Verify generation hasn't changed (TOCTOU detection)
            if self.generation.load(Ordering::Acquire) != old_gen {
                return Err(()); // Concurrent modification detected
            }

            // Attempt CAS
            if self.state.compare_exchange(
                old_state,
                new_state,
                Ordering::Release,
                Ordering::Acquire,
            ).is_ok() {
                // Increment generation on successful update
                self.generation.fetch_add(1, Ordering::Release);
                return Ok(());
            }
        }
    }
}

