use atomic_capsule::patterns::DualAtomicU64;

#[repr(C, align(64))]
#[derive(ComputationalCapsule)]
pub struct ScatteredAtomicsCapsule {
    // Bit-packed into single DualAtomicU64 (primary + secondary)
    // Primary: state(8) | count(16) | flags(32) | unused(8)
    // Secondary: generation(32) | reserved(32)
    metadata: DualAtomicU64,
    _padding: [u8; 48],      // Total: 16 bytes (2 × AtomicU64)
}

impl ScatteredAtomicsCapsule {
    // Helper methods for bit extraction
    fn load_state(&self) -> u8 {
        let primary = self.metadata.load_primary(Ordering::Acquire);
        (primary & 0xFF) as u8
    }

    fn load_count(&self) -> u16 {
        let primary = self.metadata.load_primary(Ordering::Acquire);
        ((primary >> 8) & 0xFFFF) as u16
    }

    fn load_flags(&self) -> u32 {
        let primary = self.metadata.load_primary(Ordering::Acquire);
        ((primary >> 24) & 0xFFFFFFFF) as u32
    }

    fn load_generation(&self) -> u32 {
        let secondary = self.metadata.load_secondary(Ordering::Acquire);
        (secondary & 0xFFFFFFFF) as u32
    }
}

