example5-missing-generation.before:
use core::sync::atomic::{AtomicU64, Ordering};

#[repr(C, align(64))]
pub struct RateLimiterCapsule {
    tokens: AtomicU64,        // 8 bytes
    last_refill: AtomicU64,   // 8 bytes
    // ← Missing generation counter (TOCTOU vulnerable)
    _padding: [u8; 48],       // 64 - 16 = 48 bytes
}

// Manual verification passes (doesn't check for generation counter)
crate::verification::verify_capsule_properties!(RateLimiterCapsule, 64, 64);

impl RateLimiterCapsule {
    // TOCTOU vulnerability: tokens/last_refill can change between loads
    pub fn check_and_consume(&self) -> bool {
        let tokens = self.tokens.load(Ordering::Acquire);  // ← Time-Of-Check
        let last = self.last_refill.load(Ordering::Acquire);

        // Race window: Another thread could modify tokens here

        if tokens > 0 {
            // Time-Of-Use: tokens might have changed since check
            self.tokens.fetch_sub(1, Ordering::Release);  // ← Unsafe without generation
            true
        } else {
            false
        }
    }
}

example5-missing-generation.after:
use core::sync::atomic::{AtomicU64, AtomicU32, Ordering};

#[repr(C, align(64))]
#[derive(ComputationalCapsule)]  // ← P0 deny: Detects missing generation
pub struct RateLimiterCapsule {
    tokens: AtomicU64,        // 8 bytes
    last_refill: AtomicU64,   // 8 bytes
    generation: AtomicU32,    // 4 bytes ← TOCTOU prevention
    _padding: [u8; 44],       // 64 - 20 = 44 bytes
}

// Compile-time error from clippy:
// error: capsule-missing-generation (deny)
//   --> src/patterns/rate_limiter.rs:4:1
//    |
// 4  | pub struct RateLimiterCapsule {
//    | ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ Missing generation counter (TOCTOU prevention required)
//    |
//    = help: add generation: AtomicU32 field and increment on every state update

impl RateLimiterCapsule {
    // TOCTOU-safe implementation with generation counter
    pub fn check_and_consume(&self) -> bool {
        loop {
            let gen_before = self.generation.load(Ordering::Acquire);
            let tokens = self.tokens.load(Ordering::Acquire);

            // Verify generation unchanged (detect concurrent modifications)
            if self.generation.load(Ordering::Acquire) != gen_before {
                continue; // Retry if generation changed
            }

            if tokens > 0 {
                // Atomic decrement with generation increment
                if self.tokens.compare_exchange(
                    tokens,
                    tokens - 1,
                    Ordering::Release,
                    Ordering::Acquire,
                ).is_ok() {
                    self.generation.fetch_add(1, Ordering::Release);
                    return true;
                }
            } else {
                return false;
            }
        }
    }
}

example6-non-atomic-field.before:
#[repr(C, align(64))]
pub struct StatsCollectorCapsule {
    count: u64,               // ← P0 violation: Not atomic (data race)
    sum: AtomicU64,           // 8 bytes
    _padding: [u8; 48],       // 64 - 16 = 48 bytes
}

// Manual verification passes (doesn't check field atomicity)
crate::verification::verify_capsule_properties!(StatsCollectorCapsule, 64, 64);

impl StatsCollectorCapsule {
    pub fn increment(&self, value: u64) {
        // ← DATA RACE: count is not atomic
        // Multiple threads can read/write simultaneously
        self.count += 1;  // Undefined behavior
        self.sum.fetch_add(value, Ordering::Release);
    }
}

example6-non-atomic-field.after:
use core::sync::atomic::{AtomicU64, Ordering};

#[repr(C, align(64))]
#[derive(ComputationalCapsule)]  // ← P0 deny: Detects non-atomic field
pub struct StatsCollectorCapsule {
    count: AtomicU64,         // ← Fixed: Atomic (data race eliminated)
    sum: AtomicU64,           // 8 bytes
    _padding: [u8; 48],       // 64 - 16 = 48 bytes
}

// Compile-time error from clippy:
// error: capsule-non-atomic-field (deny)
//   --> src/collections/stats.rs:3:5
//    |
// 3  |     count: u64,
//    |     ^^^^^^^^^^ Non-atomic field not allowed (data race risk)
//    |
//    = help: replace with AtomicU64 for thread-safe coordination

impl StatsCollectorCapsule {
    pub fn increment(&self, value: u64) {
        // ← No data race: both fields atomic
        self.count.fetch_add(1, Ordering::Release);
        self.sum.fetch_add(value, Ordering::Release);
    }
}

