pattern1-mutex-to-atomic.code-transformation:
// BEFORE: Mutex-based coordination
fn increment_with_mutex(&self) {
    let mut guard = self.count.lock().unwrap();
    *guard += 1;
    // Lock held during entire operation
}

// AFTER: Atomic-based coordination
fn increment_with_atomic(&self) {
    self.count.fetch_add(1, Ordering::Release);
    // No lock, 100% lockfree
}

// BEFORE: RwLock for complex data
fn update_with_rwlock(&self, new_data: Data) {
    let mut guard = self.data.write().unwrap();
    *guard = new_data;
}

// AFTER: AtomicPtr with heap allocation
fn update_with_atomic_ptr(&self, new_data: Data) {
    let boxed = Box::new(new_data);
    let ptr = Box::into_raw(boxed);
    let old = self.data.swap(ptr, Ordering::AcqRel);
    if !old.is_null() {
        unsafe { drop(Box::from_raw(old)); }  // Free old allocation
    }
}

pattern3-add-generation.implementation-pattern:
// Step 1: Add generation field to struct
#[repr(C, align(64))]
#[derive(ComputationalCapsule)]
pub struct RateLimiterCapsule {
    tokens: AtomicU64,
    last_refill: AtomicU64,
    generation: AtomicU32,  // ← NEW: 4 bytes
    _padding: [u8; 44],     // ← ADJUSTED: 48 - 4 = 44 bytes
}

// Step 2: Update methods to use generation
impl RateLimiterCapsule {
    // Pattern: Load generation FIRST, then data, then verify generation AGAIN
    pub fn check_and_consume(&self) -> bool {
        loop {
            // Step 1: Capture generation before reading data
            let gen_before = self.generation.load(Ordering::Acquire);

            // Step 2: Read data (tokens, last_refill)
            let tokens = self.tokens.load(Ordering::Acquire);
            let last = self.last_refill.load(Ordering::Acquire);

            // Step 3: Verify generation unchanged (TOCTOU detection)
            let gen_after = self.generation.load(Ordering::Acquire);
            if gen_before != gen_after {
                continue; // Retry if concurrent modification detected
            }

            // Step 4: Perform operation with CAS
            if tokens > 0 {
                if self.tokens.compare_exchange(
                    tokens,
                    tokens - 1,
                    Ordering::Release,
                    Ordering::Acquire,
                ).is_ok() {
                    // Step 5: Increment generation on successful update
                    self.generation.fetch_add(1, Ordering::Release);
                    return true;
                }
            } else {
                return false;
            }
        }
    }
}

pattern3-add-generation.verification-pattern:
// Property test: Generation increments monotonically
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generation_monotonic() {
        let capsule = RateLimiterCapsule::new(1000);

        let gen1 = capsule.generation.load(Ordering::Acquire);
        capsule.check_and_consume(); // Perform operation
        let gen2 = capsule.generation.load(Ordering::Acquire);

        assert!(gen2 > gen1, "Generation must increase after update");
        assert_eq!(gen2 - gen1, 1, "Generation should increment by 1");
    }

    #[test]
    fn test_toctou_detection() {
        use std::sync::Arc;
        use std::thread;

        let capsule = Arc::new(RateLimiterCapsule::new(1000));
        let capsule2 = Arc::clone(&capsule);

        // Thread 1: Read generation before operation
        let gen_before = capsule.generation.load(Ordering::Acquire);

        // Thread 2: Concurrent modification
        thread::spawn(move || {
            capsule2.check_and_consume();
        }).join().unwrap();

        // Thread 1: Verify generation changed (TOCTOU detected)
        let gen_after = capsule.generation.load(Ordering::Acquire);
        assert_ne!(gen_before, gen_after, "TOCTOU detection must work");
    }
}

pattern4-fix-non-atomic-fields.access-pattern-updates:
// BEFORE: Direct field access (data race)
pub fn increment(&mut self) {
    self.count += 1;  // ← Data race if called from multiple threads
}

pub fn read(&self) -> u64 {
    self.count  // ← Data race if another thread is writing
}

// AFTER: Atomic field access (thread-safe)
pub fn increment(&self) {  // ← Note: &self (not &mut self)
    self.count.fetch_add(1, Ordering::Release);
}

pub fn read(&self) -> u64 {
    self.count.load(Ordering::Acquire)
}

// BEFORE: Conditional update (data race)
pub fn update_if_greater(&mut self, new_value: u64) {
    if new_value > self.max {  // ← TOCTOU race
        self.max = new_value;
    }
}

// AFTER: Atomic compare-exchange (race-free)
pub fn update_if_greater(&self, new_value: u64) {
    loop {
        let current = self.max.load(Ordering::Acquire);
        if new_value <= current {
            break;  // New value not greater, no update needed
        }

        // Atomic CAS: only update if value unchanged since load
        if self.max.compare_exchange(
            current,
            new_value,
            Ordering::Release,
            Ordering::Acquire,
        ).is_ok() {
            break;  // Update succeeded
        }
        // CAS failed (concurrent modification), retry loop
    }
}

issue.fix:
# Add to Cargo.toml [dependencies] atomic_capsule_derive = { version = "0.4.0", path = "../atomic_capsule_derive" }
# Or install from crates.io (when published) atomic_capsule_derive = "0.4.0"
# Ensure derive macro is re-exported in lib.rs pub use atomic_capsule_derive::ComputationalCapsule;

// Example: Mutex hidden in nested struct
#[repr(C, align(64))]
#[derive(ComputationalCapsule)]
pub struct ParentCapsule {
    child: ChildStruct,  // ← Contains Mutex internally
    _padding: [u8; 48],
}

#[repr(C)]
struct ChildStruct {
    data: Mutex<u64>,  // ← P0 violation (found by recursive check)
}

// FIX: Replace Mutex in nested struct
#[repr(C)]
struct ChildStruct {
    data: AtomicU64,  // ← Fixed
}

// BEFORE: Relaxed ordering (insufficient synchronization)
let value = self.state.load(Ordering::Relaxed);
self.state.store(new_value, Ordering::Relaxed);

// AFTER: Acquire/Release ordering (proper synchronization)
let value = self.state.load(Ordering::Acquire);  // ← Synchronize reads
self.state.store(new_value, Ordering::Release);  // ← Synchronize writes

// Rule of thumb:
// - Acquire for loads (synchronize before dependent reads)
// - Release for stores (synchronize after all writes)
// - AcqRel for RMW operations (fetch_add, compare_exchange)

// Suppress warning with #[allow(dead_code)]
#[repr(C, align(64))]
#[derive(ComputationalCapsule)]
pub struct MyCapsule {
    state: AtomicU64,
    #[allow(dead_code)]  // ← Suppress warning
    _padding: [u8; 56],
}

// Or use underscore prefix (Rust convention)
_padding: [u8; 56],  // ← Already suppresses by naming convention

# Workaround 1: Disable specific lint temporarily #[allow(clippy::capsule-incorrect-padding)] #[derive(ComputationalCapsule)] pub struct ProblematicCapsule { ... }
# Workaround 2: Update clippy to latest version rustup update nightly cargo +nightly clippy --version # Verify newer version
# Workaround 3: Report bug with minimal reproduction # (See clippy-capsule-verify GitHub issues)

// Verify #[repr(C)] is present
#[repr(C, align(64))]  // ← Must have both C and align
#[derive(ComputationalCapsule)]
pub struct MyCapsule { ... }

// Runtime validation (sanity check)
#[test]
fn test_capsule_size() {
    assert_eq!(std::mem::size_of::<MyCapsule>(), 64);
    assert_eq!(std::mem::align_of::<MyCapsule>(), 64);
}
